// Owner: P0 (土台). Left rail item list (desktop, 1280px and wider; SPEC 1.1 and 1.2).
// Items come from NAV_SCREENS. The threats item is creator-only (D1). P1-P8 do not edit this file.
import { useTranslation } from 'react-i18next';
import { CREATOR_ONLY_SCREENS, NAV_SCREENS } from '../types/screen';
import type { ScreenId } from '../types/screen';
import { useMission } from './MissionContext';
import { useWorkspace } from './workspace';

export function WorkspaceNav() {
  const { t } = useTranslation('shell');
  const { viewMode } = useMission();
  const { screen, setScreen } = useWorkspace();
  const items = NAV_SCREENS.filter(id => viewMode === 'creator' || !CREATOR_ONLY_SCREENS.includes(id));

  return (
    <nav className="workspace-nav" aria-label={t('shell:rail.navLabel')}>
      <ul className="workspace-nav-list">
        {items.map((id: ScreenId) => (
          <li key={id}>
            <button
              type="button"
              className={`workspace-nav-item${screen === id ? ' is-current' : ''}`}
              aria-current={screen === id ? 'page' : undefined}
              onClick={() => setScreen(id)}
            >
              {t(`nav.${id}`)}
            </button>
          </li>
        ))}
      </ul>
    </nav>
  );
}
